files.content:
.stepper {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}

/* Each step takes an equal share and grows a connecting line to its right. */
.stepper-step {
  position: relative;
  flex: 1;
  min-inline-size: 0;
}
.stepper-step:not(:last-child)::after {
  content: '';
  position: absolute;
  inset-block-start: calc(var(--space-6) / 2);
  inset-inline-start: calc(50% + var(--space-4));
  inline-size: calc(100% - var(--space-8));
  block-size: 2px;
  background: var(--border);
}
.stepper-step[data-state='complete']:not(:last-child)::after {
  background: var(--primary);
}

.stepper-button {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-1);
  inline-size: 100%;
  padding: 0;
  border: none;
  background: transparent;
  font: inherit;
  text-align: center;
  color: var(--muted-foreground);
}
button.stepper-button {
  cursor: pointer;
}
/* A step you can go back to is a control, and it said nothing under the pointer. */
button.stepper-button:hover .stepper-marker { border-color: var(--ring); }
button.stepper-button:hover .stepper-text { color: var(--foreground); }
button.stepper-button:active .stepper-marker { border-color: var(--primary-active); }
button.stepper-button:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
  border-radius: var(--radius-md);
}

.stepper-marker {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--space-6);
  block-size: var(--space-6);
  border-radius: var(--radius-full);
  border: 2px solid var(--border);
  background: var(--background);
  font-size: var(--font-sm);
  font-weight: var(--font-weight-semibold);
  font-variant-numeric: tabular-nums;
  z-index: 1;
}
.stepper-step[data-state='complete'] .stepper-marker {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--primary-foreground);
}
.stepper-step[data-state='current'] .stepper-marker {
  border-color: var(--primary);
  color: var(--primary-accent);
}

.stepper-text {
  display: flex;
  flex-direction: column;
  gap: var(--space-2xs);
}
.stepper-label {
  font-size: var(--font-sm);
  font-weight: var(--font-weight-medium);
}
.stepper-step[data-state='current'] .stepper-label,
.stepper-step[data-state='complete'] .stepper-label {
  color: var(--foreground);
}
.stepper-description {
  font-size: var(--font-xs);
  color: var(--muted-foreground);
}

import './Stepper.css'
import { cn } from '../lib/cn'
import { Icon } from '../Icon'

export type Step = {
  label: string
  /** Optional line under the label. */
  description?: string
}

type Props = {
  steps: Step[]
  /** 0-based index of the step in progress. Earlier steps read as complete. */
  current: number
  /** Lets the user jump back to a completed step. Only completed steps are
   *  interactive; the current and future ones are not. */
  onStepClick?: (index: number) => void
  /** Accessible name for the ordered list. Default "Progress". */
  label?: string
  className?: string
}

/* Progress across an ordered set of steps (a wizard, a multi-step form). Shows
 * which are done (check), which is active (aria-current="step") and which are
 * still ahead. Presentational: the parent owns `current` and what each step
 * contains. Completed steps can be clickable to go back. 
   *
   * Copy: step names are nouns, short and parallel, and they stay the same word in
   * the step and in its page title.
   */
export function Stepper({ steps, current, onStepClick, label = 'Progress', className }: Props) {
  return (
    <ol className={cn('stepper', className)} aria-label={label}>
      {steps.map((step, i) => {
        const state = i < current ? 'complete' : i === current ? 'current' : 'upcoming'
        const clickable = state === 'complete' && onStepClick
        const marker = (
          <span className="stepper-marker" aria-hidden="true">
            {state === 'complete' ? <Icon name="check" /> : i + 1}
          </span>
        )
        const body = (
          <span className="stepper-text">
            <span className="stepper-label">{step.label}</span>
            {step.description && <span className="stepper-description">{step.description}</span>}
          </span>
        )
        return (
          <li key={step.label} className="stepper-step" data-state={state} aria-current={state === 'current' ? 'step' : undefined}>
            {clickable ? (
              <button type="button" className="stepper-button" onClick={() => onStepClick(i)}>
                {marker}
                {body}
              </button>
            ) : (
              <span className="stepper-button">
                {marker}
                {body}
              </span>
            )}
          </li>
        )
      })}
    </ol>
  )
}
